mapper.select:


    ${params.dataScope}
    and w.del_flag = '0'
     and w.status = #{status}
     and w.title like concat('%', #{title}, '%')
     and w.reader_id = #{readerId}

order by w.create_time desc

select count(1) from book_wish
where reader_id = #{readerId} and title = #{title}
  and status in ('0','1','3') and del_flag = '0'
